package com.game_manager.gm.machine;import static com.game_manager.gm.machine.dto.MachineDtos.*;import com.game_manager.gm.common.error.ApplicationException;import com.game_manager.gm.gamingsession.*;import com.game_manager.gm.gamingsession.command.*;import com.game_manager.gm.machine.dto.StationLeaseDtos.SessionLeasePayload;import com.game_manager.gm.station.*;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.ObjectMapper;
@Service public class StationLeaseService {@org.springframework.beans.factory.annotation.Autowired private org.springframework.jdbc.core.JdbcTemplate jdbc;private final MachinePrincipalProvider principal;private final GamingSessionRepository sessions;private final GamingStationProfileRepository stations;private final ApplicationProfileRepository profiles;private final StationHeartbeatRepository heartbeats;private final StationCommandRepository commands;private final StationPolicySigner signer;private final StationEnforcementProjectionService enforcement;private final ObjectMapper json;private final Clock clock;private final Duration duration,grace;@org.springframework.beans.factory.annotation.Autowired private com.game_manager.gm.common.scheduling.ClientUpdatePort updates; @org.springframework.beans.factory.annotation.Autowired private com.game_manager.gm.gamingsession.billing.MeteredSessionRuntime metered;
 public StationLeaseService(MachinePrincipalProvider principal,GamingSessionRepository sessions,GamingStationProfileRepository stations,ApplicationProfileRepository profiles,StationHeartbeatRepository heartbeats,StationCommandRepository commands,StationPolicySigner signer,StationEnforcementProjectionService enforcement,ObjectMapper json,Clock clock,@Value("${app.gaming-client.lease-duration-seconds:30}")long duration,@Value("${app.gaming-client.offline-grace-seconds:30}")long grace){this.principal=principal;this.sessions=sessions;this.stations=stations;this.profiles=profiles;this.heartbeats=heartbeats;this.commands=commands;this.signer=signer;this.enforcement=enforcement;this.json=json;this.clock=clock;this.duration=Duration.ofSeconds(duration);this.grace=Duration.ofSeconds(grace);}
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public SignedSessionLease lease(){MachinePrincipal machine=principal.require();Instant now=clock.instant();GamingStationProfile station=stations.findByResourceId(machine.stationId()).orElseThrow(()->new ApplicationException(HttpStatus.NOT_FOUND,"Station not found"));long configVersion=station.getApplicationProfileId()==null?0:profiles.findById(station.getApplicationProfileId()).map(ApplicationProfile::getConfigurationVersion).orElse(0L);GamingSession session=sessions.findByResourceIdAndStatus(machine.stationId(),GamingSessionStatus.ACTIVE).orElse(null);if(session!=null && session.getBillingMode()==GamingBillingMode.PREPAID_METERED){metered.tick(session.getId(),true);}boolean active=session!=null&&session.getStatus()==GamingSessionStatus.ACTIVE&&session.getMoveTargetId()==null&&session.getEndsAt().isAfter(now);long cursor=commands.currentCursor(machine.stationId().toString());Instant nominalExpiry=now.plus(duration);Instant expires=active&&session.getEndsAt().isBefore(nominalExpiry)?session.getEndsAt():nominalExpiry;if(active && session.getBillingMode()==GamingBillingMode.PREPAID_METERED && session.getMeteredLeaseUntil().isBefore(expires)) expires=session.getMeteredLeaseUntil();Instant graceEnd=active&&session.getEndsAt().isBefore(expires.plus(grace))?session.getEndsAt():expires.plus(grace);if(active && session.getBillingMode()==GamingBillingMode.PREPAID_METERED) {graceEnd=expires;session.setMeteredLeaseUntil(expires);}UUID leaseId=UUID.randomUUID();java.math.BigDecimal credit=active && session.getBillingMode()==GamingBillingMode.PREPAID_METERED?jdbc.queryForObject("SELECT COALESCE(SUM(amount),0) FROM gaming_wallet_ledger WHERE customer_id=?",java.math.BigDecimal.class,session.getCustomerId().toString()):null;SessionLeasePayload payload=new SessionLeasePayload(leaseId,machine.stationId(),active?session.getId():null,active?session.getCustomerId():null,active?session.getEndsAt():null,configVersion,now,expires,graceEnd,cursor,active?"ACTIVE":"LOCK",updates.directive(machine.stationId()),active?session.getBillingMode().name():null,active?session.getStartedAt():null,credit,active?session.getChargedAmount():null,credit==null?null:accessEndReason(session,credit));try{byte[] bytes=json.writeValueAsBytes(payload);enforcement.leaseIssued(machine,leaseId,payload.sessionId(),expires,configVersion,cursor);return new SignedSessionLease(Base64.getUrlEncoder().withoutPadding().encodeToString(bytes),"Ed25519",signer.keyId(),signer.sign(bytes));}catch(Exception e){if(e instanceof ApplicationException application)throw application;throw new ApplicationException(HttpStatus.INTERNAL_SERVER_ERROR,"Station lease could not be serialized");}}
 private String accessEndReason(GamingSession s,java.math.BigDecimal credit){long seconds=com.game_manager.gm.gamingsession.billing.MeteredPricing.affordable(credit.add(s.getChargedAmount()),s.getMeteredPrice(),s.getMeteredTariffSeconds(),s.getBillingUnitSeconds());return s.getEndsAt().isBefore(s.getStartedAt().plusSeconds(seconds))?"BOUNDARY":"CREDIT";}
 @Transactional public LockAckResponse lockAck(LockAckRequest request){MachinePrincipal machine=principal.require();StationCommand command=commands.findByStationIdAndSequence(machine.stationId(),request.commandSequence()).filter(value->value.getSessionId().equals(request.sessionId())&&(value.getCommandType()==StationCommandType.SESSION_TERMINATED||value.getCommandType()==StationCommandType.FORCE_LOCK)).orElseThrow(()->new ApplicationException(HttpStatus.CONFLICT,"Lock acknowledgement does not match a lock command"));Instant at=enforcement.lockAck(machine,request.sessionId(),request.commandSequence(),request.leaseId(),request.reason());if(command.getAcknowledgedAt()==null){command.setAcknowledgedAt(at);commands.save(command);}return new LockAckResponse(machine.stationId(),request.sessionId(),request.commandSequence(),at,StationEnforcementStatus.LOCKED.name());}
}
